import type { HTMLAttributes } from "react";
import { cx } from "../utils/cx";

/** A keyboard key cap: `<Kbd>⌘</Kbd><Kbd>K</Kbd>`. Server-compatible. */
export function Kbd({ className, ...rest }: HTMLAttributes<HTMLElement>) {
  return <kbd {...rest} className={cx("hm-kbd", className)} />;
}

/** Several keys that are pressed together, joined by a quiet plus. */
export function KbdGroup({ className, ...rest }: HTMLAttributes<HTMLSpanElement>) {
  return <span {...rest} className={cx("hm-kbd-group", className)} />;
}
